#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::string line;
    std::getline(std::cin, line); // consume the remaining newline after reading n
    std::getline(std::cin, line);

    int maxSegmentLength = 0;
    int bracketsCount = 0;
    std::string outsideStr;
    std::string insideStr;

    for (int i = 0; i < n; i++) {
        if (line[i] == '(') {
            outsideStr += "_";
            i++;
            while (i < n && line[i] != ')') {
                insideStr += line[i];
                i++;
            }
            insideStr += "_";
        } else {
            outsideStr += line[i];
        }
    }

    std::vector<std::string> outsideParts;
    size_t start = 0, end;
    while ((end = outsideStr.find('_', start)) != std::string::npos) {
        outsideParts.push_back(outsideStr.substr(start, end - start));
        start = end + 1;
    }
    if (start < outsideStr.size()) {
        outsideParts.push_back(outsideStr.substr(start));
    }

    for (const auto& part : outsideParts) {
        maxSegmentLength = std::max(maxSegmentLength, (int)part.length());
    }

    std::vector<std::string> insideParts;
    start = 0;
    while ((end = insideStr.find('_', start)) != std::string::npos) {
        std::string segment = insideStr.substr(start, end - start);
        if (!segment.empty()) {
            bracketsCount++;
        }
        start = end + 1;
    }
    // Check for last segment if any
    if (start < insideStr.size()) {
        if (!insideStr.substr(start).empty()) {
            bracketsCount++;
        }
    }

    std::cout << maxSegmentLength << " " << bracketsCount << std::endl;
    return 0;
